mapper.select:
select

from survey_franchisee_price
where delete_flag = 0

    and franchisee_id = #{franchiseeId,jdbcType=BIGINT}


    and task_id = #{taskId,jdbcType=BIGINT}


    and area_id = #{areaId,jdbcType=INTEGER}


    and city_type = #{cityType,jdbcType=INTEGER}


    and task_info_content_id = #{taskInfoContentId,jdbcType=BIGINT}


    and direction_result_type_id = #{directionResultTypeId,jdbcType=BIGINT}


    and price_type = #{priceType,jdbcType=INTEGER}

limit 1;

mapper.delete:
delete from survey_franchisee_price
where franchisee_id = #{franchiseeId,jdbcType=BIGINT} and area_id = #{areaId,jdbcType=INTEGER}
  and price_type = #{priceType,jdbcType=INTEGER}
